import test from 'node:test';
import assert from 'node:assert/strict';
import {JSDOM} from 'jsdom';
import JSZip from 'jszip';
import {applyPublisherStyles} from './.generated/readers/publisher-styles.js';
import {projectHtml,describeRange,resolveHtml} from './.generated/readers/dom-source.js';
import {openPublication} from './.generated/readers/epub-book.js';
function host(html){
 const dom=new JSDOM('<body><aside id="host" style="color:blue">Host UI</aside><main></main></body>'),doc=dom.window.document;
 const original=new dom.window.DOMParser().parseFromString(html,'text/html').body,root=doc.querySelector('main'),projection=projectHtml(original,root);
 return{dom,doc,original,root,projection,close:()=>dom.window.close()};
}
const book=(files={})=>({text:async path=>{if(!(path in files))throw Error('Missing asset');return files[path];}});
test('publisher cascade uses inert original selectors and inline priorities without adopting host classes or CSS',async()=>{
 const h=host(`<html><head><style>html {color:maroon} body {text-align:justify} p {margin:1em;color:red} .lead {color:green} #title {color:purple!important} p.lead {font-style:italic} .theme-dark {font-weight:700}</style></head><body><p id="title" class="lead theme-dark" style="color:orange">First passage</p><p class="lead">Second passage</p></body></html>`);
 try{
 const result=await applyPublisherStyles(book(),'OPS/chapter.xhtml',h.projection,()=>true);const [first,second]=h.root.querySelectorAll('p');
 assert.equal(first.style.color,'purple');assert.equal(first.style.getPropertyPriority('color'),'important');assert.equal(first.style.fontStyle,'italic');assert.equal(first.style.fontWeight,'700');assert.equal(first.style.marginTop,'1em');assert.equal(second.style.color,'green');assert.equal(h.root.style.textAlign,'justify');assert.equal(h.root.style.color,'maroon');
 assert.equal(first.className,'');assert.equal(h.doc.querySelector('#host').style.color,'blue');assert.equal(h.doc.querySelectorAll('style,link').length,0);assert.equal(result.omitted,0);
 const source=h.original.querySelector('p').firstChild,range=h.original.ownerDocument.createRange();range.setStart(source,0);range.setEnd(source,5);const selectors=describeRange(h.original,range);assert.equal(h.projection.toRendered(resolveHtml(h.original,selectors)).toString(),'First');assert.equal(h.projection.toOriginal(h.projection.toRendered(range)).toString(),'First');result.dispose();
 }finally{h.close();}
});
test('local stylesheet imports resolve against their own archive path, keep source order, and break cycles',async()=>{
 const h=host('<head><link rel="stylesheet" href="../styles/book.css"></head><body><p>Styled locally</p></body>'),reads=[];
 try{
 const files={'styles/book.css':'@import "extra/base.css"; p {color:navy}', 'styles/extra/base.css':'@import "../book.css"; p {color:red;line-height:1.8}'};
 const result=await applyPublisherStyles({text:async path=>{reads.push(path);return files[path];}},'OPS/chapter.xhtml',h.projection,()=>true);
 assert.deepEqual(reads,['styles/book.css','styles/extra/base.css']);assert.equal(h.root.querySelector('p').style.color,'navy');assert.equal(h.root.querySelector('p').style.lineHeight,'1.8');assert.equal(result.omitted,0);
 }finally{h.close();}
});
test('network CSS, dynamic selectors, generated text, URLs and host-affecting properties are omitted explicitly',async()=>{
 const h=host(`<head><link rel="stylesheet" href="https://example.test/book.css"><style>@import url(https://example.test/import.css); @media print { p{color:red} } p::before{content:'invented text'} p:has(a){color:red} p {position:fixed;z-index:9999;background-image:url(https://example.test/track);font-family:var(--host-font);color:expression(alert(1));margin-left:999999px;text-align:center}</style></head><body><p style="background-color:url(https://example.test/inline);text-indent:2em">Original text</p></body>`);let requests=0;
 try{
 const result=await applyPublisherStyles({text:async()=>{requests++;throw Error();}},'OPS/c.xhtml',h.projection,()=>true),p=h.root.querySelector('p');
 assert.equal(requests,0);assert.ok(result.omitted>=10);assert.equal(p.style.position,'');assert.equal(p.style.backgroundImage,'');assert.equal(p.style.fontFamily,'unset');assert.equal(p.style.color,'');assert.equal(p.style.marginLeft,'');assert.equal(p.style.textAlign,'center');assert.equal(p.style.textIndent,'2em');assert.equal(p.textContent,'Original text');assert.equal(h.doc.querySelectorAll('style,link').length,0);
 }finally{h.close();}
});
test('packaged fonts receive unique host names, complete before use, and are removed on disposal',async()=>{
 const h=host(`<head><style>@font-face {font-family:'Book Face';src:url('../fonts/book.woff2') format('woff2');font-weight:400} p {font-family:'Book Face', serif}</style></head><body><p>Custom font passage</p></body>`),faces=new Set(),reads=[];let calls=0;
 h.dom.window.FontFace=class{constructor(family,bytes,descriptors){this.family=family;this.bytes=bytes;this.descriptors=descriptors;calls++;}async load(){return this;}};Object.defineProperty(h.doc,'fonts',{value:{add:face=>faces.add(face),delete:face=>faces.delete(face)}});
 try{
 const result=await applyPublisherStyles({...book(),font:async path=>{reads.push(path);return new Uint8Array([119,79,70,50]);}},'OPS/chapter.xhtml',h.projection,()=>true);
 assert.deepEqual(reads,['fonts/book.woff2']);assert.equal(calls,1);assert.equal(faces.size,1);const face=[...faces][0];assert.match(face.family,/^annotator-publisher-\d+-[a-z0-9]+$/);assert.equal(face.descriptors.weight,'400');assert.ok(h.root.querySelector('p').style.fontFamily.includes(face.family));assert.equal(result.omitted,0);result.dispose();result.dispose();assert.equal(faces.size,0);
 }finally{h.close();}
});
test('a font completing after a chapter is replaced never enters the host font set',async()=>{
 const h=host('<head><style>@font-face{font-family:Book;src:url(book.ttf)}p{font-family:Book}</style></head><body><p>Old chapter</p></body>');let release,started,current=true;const begun=new Promise(r=>started=r);const faces=new Set();
 h.dom.window.FontFace=class{async load(){started();await new Promise(r=>release=r);return this;}};Object.defineProperty(h.doc,'fonts',{value:{add:f=>faces.add(f),delete:f=>faces.delete(f)}});
 try{const pending=applyPublisherStyles({...book(),font:async()=>new Uint8Array([0,1,0,0])},'c.xhtml',h.projection,()=>current);await begun;current=false;release();const result=await pending;assert.equal(faces.size,0);assert.equal(h.root.querySelector('p').style.fontFamily,'');result.dispose();}finally{h.close();}
});
test('invalid and encrypted font bytes are refused by the publication archive boundary',async()=>{
 const h=host('<p>Book</p>'),zip=new JSZip();zip.file('META-INF/container.xml','<container><rootfile full-path="book.opf"/></container>');zip.file('book.opf','<package><manifest><item id="c" href="c.xhtml" media-type="application/xhtml+xml"/></manifest><spine><itemref idref="c"/></spine></package>');zip.file('c.xhtml','<body>Book</body>');zip.file('valid.woff2',new Uint8Array([119,79,70,50,1,2]));zip.file('invalid.ttf','not a font');zip.file('encrypted.ttf',new Uint8Array([0,1,0,0,1,2]));zip.file('META-INF/encryption.xml','<encryption><EncryptedData><EncryptionMethod Algorithm="http://www.idpf.org/2008/embedding"/><CipherData><CipherReference URI="encrypted.ttf"/></CipherData></EncryptedData></encryption>');
 try{const publication=await openPublication(await zip.generateAsync({type:'arraybuffer'}),h.doc);assert.deepEqual([...await publication.font('valid.woff2')],[119,79,70,50,1,2]);assert.equal(await publication.font('invalid.ttf'),null);assert.equal(await publication.font('encrypted.ttf'),null);assert.equal(await publication.font('missing.ttf'),null);}finally{h.close();}
});

test('repeated stylesheet links retain cascade position while sharing the bounded archive read',async()=>{
 const h=host('<head><link rel="stylesheet" href="a.css"><link rel="stylesheet" href="b.css"><link rel="stylesheet" href="a.css"></head><body><p>Repeated cascade</p></body>'),reads=[];
 try{const result=await applyPublisherStyles({text:async p=>{reads.push(p);return p==='a.css'?'p{color:red;margin-left:2em!important}':'p{color:blue;margin:3em}';}},'c.xhtml',h.projection,()=>true);const p=h.root.querySelector('p');assert.deepEqual(reads,['a.css','b.css']);assert.equal(p.style.color,'red');assert.equal(p.style.marginLeft,'2em');assert.equal(p.style.marginRight,'3em');assert.equal(result.omitted,0);}finally{h.close();}
});

test('complete styled EPUB fixture retains original selectors and validates its packaged font',async()=>{
 const {publisherBook}=await import('./support/publisher-fixture.mjs'),h=host('<p>Host</p>');
 h.dom.window.FontFace=class{async load(){return this;}};const faces=new Set();Object.defineProperty(h.doc,'fonts',{value:{add:f=>faces.add(f),delete:f=>faces.delete(f)}});
 try{const bytes=await publisherBook(),publication=await openPublication(bytes.buffer.slice(bytes.byteOffset,bytes.byteOffset+bytes.byteLength),h.doc),html=await publication.text('OPS/chapter.xhtml'),original=new h.dom.window.DOMParser().parseFromString(html,'text/html').body,projection=projectHtml(original,h.root);
 const result=await applyPublisherStyles(publication,'OPS/chapter.xhtml',projection,()=>true);assert.equal(result.omitted,0);assert.equal(faces.size,1);assert.ok((await publication.font('OPS/fonts/LiberationSans-Regular.ttf')).byteLength>1000);assert.equal(h.root.querySelector('h1').style.color,'rgb(49, 88, 187)');const source=original.querySelector('.sample').firstChild,range=original.ownerDocument.createRange();range.setStart(source,33);range.setEnd(source,43);assert.equal(range.toString(),'Liberation');assert.equal(projection.toOriginal(projection.toRendered(resolveHtml(original,describeRange(original,range)))).toString(),'Liberation');result.dispose();assert.equal(faces.size,0);
 }finally{h.close();}
});

