test('larger single fonts do not raise the cumulative mounted-chapter font budget',async()=>{
 const h=host('<head><style>@font-face{font-family:A;src:url(a.otf)}@font-face{font-family:B;src:url(b.otf)}@font-face{font-family:C;src:url(c.otf)}p{font-family:A}</style></head><body><p>Budget</p></body>'),faces=new Set(),loaded=[];
 h.dom.window.FontFace=class{constructor(family,bytes){this.family=family;this.size=bytes.byteLength;}async load(){loaded.push(this.size);return this;}};Object.defineProperty(h.doc,'fonts',{value:{add:f=>faces.add(f),delete:f=>faces.delete(f)}});
 try{const result=await applyPublisherStyles({...book(),font:async path=>new Uint8Array(path==='c.otf'?1:12_000_000)},'c.xhtml',h.projection,()=>true);assert.deepEqual(loaded,[12_000_000,12_000_000]);assert.equal(faces.size,2);assert.ok(result.omitted>=1);result.dispose();assert.equal(faces.size,0);}finally{h.close();}
});

test('publisher image markers share bounded archive assets with backgrounds and retain shorthand cascade and text coordinates',async()=>{
 const h=host('<head><link rel="stylesheet" href="styles/book.css"/></head><body><ul id="art"><li>Image bullet passage</li></ul><ul class="reset"><li>Reset bullet</li></ul><ul style="list-style:var(--bullet) none inside"><li>Inline variable bullet</li></ul><p>Shared background</p></body>'),reads=[],made=[],revoked=[];
 h.dom.window.URL.createObjectURL=()=>{const url='blob:bullet-'+made.length;made.push(url);return url;};h.dom.window.URL.revokeObjectURL=url=>revoked.push(url);
 try{
 const result=await applyPublisherStyles({...book({'OPS/styles/book.css':':root{--bullet:url(images/dot.png)}ul{list-style:url(../images/dot.png) square inside}#art{list-style-type:lower-roman}.reset{list-style:circle outside}p{background-image:url(../images/dot.png)}'}),image:async path=>{reads.push(path);return {bytes:new Uint8Array([137,80,78,71]),mime:'image/png'};}},'OPS/chapter.xhtml',h.projection,()=>true);
 const [art,reset,inline]=h.root.querySelectorAll('ul');assert.deepEqual(reads,['OPS/images/dot.png']);assert.equal(made.length,1);assert.match(art.style.listStyleImage,/blob:bullet-0/);assert.equal(art.style.listStyleType,'lower-roman');assert.equal(art.style.listStylePosition,'inside');assert.equal(reset.style.listStyleImage,'none');assert.equal(reset.style.listStyleType,'circle');assert.equal(reset.style.listStylePosition,'outside');assert.match(inline.style.listStyleImage,/blob:bullet-0/);assert.equal(inline.style.listStyleType,'none');assert.equal(inline.style.listStylePosition,'inside');assert.match(h.root.querySelector('p').style.backgroundImage,/blob:bullet-0/);assert.equal(result.omitted,0);
 const range=h.original.ownerDocument.createRange();range.selectNodeContents(h.original.querySelector('li'));assert.equal(h.projection.toRendered(range).toString(),'Image bullet passage');assert.equal(h.projection.toOriginal(h.projection.toRendered(range)).toString(),'Image bullet passage');assert.equal(h.original.querySelector('ul[style]').getAttribute('style'),'list-style:var(--bullet) none inside');result.refresh();assert.equal(made.length,1);result.dispose();result.dispose();assert.deepEqual(revoked,made);
 }finally{h.close();}
});

test('image markers reject external and escaping resources and share the chapter image-count bound',async()=>{
 const h=host('<head><style>ul{list-style-type:square}.external{list-style-image:url(https://example.org/bullet.png)}.escape{list-style:url(../../../escape.png)}.foreign{list-style-image:url(blob:foreign)}'+Array.from({length:33},(_,i)=>`.p${i}{${i%2?'background-image':'list-style-image'}:url(image${i}.png)}`).join('')+'</style></head><body><ul class="external"><li>External</li></ul><ul class="escape"><li>Escape</li></ul><ul class="foreign"><li>Foreign</li></ul>'+Array.from({length:33},(_,i)=>`<ul class="p${i}"><li>Bound ${i}</li></ul>`).join('')+'</body>'),reads=[],made=[],revoked=[];
 h.dom.window.URL.createObjectURL=()=>{const url='blob:bounded-bullet-'+made.length;made.push(url);return url;};h.dom.window.URL.revokeObjectURL=url=>revoked.push(url);
 try{const result=await applyPublisherStyles({...book(),image:async path=>{reads.push(path);return{bytes:new Uint8Array([137,80,78,71]),mime:'image/png'};}},'OPS/chapter.xhtml',h.projection,()=>true);assert.equal(reads.length,32);assert.ok(reads.every(path=>/^OPS\/image\d+\.png$/.test(path)));assert.equal(made.length,32);for(const node of [...h.root.querySelectorAll('ul')].slice(0,3)){assert.equal(node.style.listStyleImage,'');assert.equal(node.style.listStyleType,'square');}assert.equal(h.root.lastElementChild.style.listStyleImage,'');assert.ok(result.omitted>=4);result.dispose();assert.deepEqual(revoked,made);}finally{h.close();}
});

test('responsive variable image markers refresh after loading and discard late resources after disposal',async()=>{
 const h=host('<head><style>:root{--marker:url(small.png)}@media(min-width:600px){:root{--marker:url(large.png)}}ul{list-style:var(--marker) square inside}</style></head><body><ul><li>Responsive bullet</li></ul></body>');let width=400,release,changed=0;const reads=[],made=[],revoked=[];
 h.dom.window.URL.createObjectURL=()=>{const url='blob:responsive-marker-'+made.length;made.push(url);return url;};h.dom.window.URL.revokeObjectURL=url=>revoked.push(url);
 try{const result=await applyPublisherStyles({...book(),image:async path=>{reads.push(path);if(path==='large.png')await new Promise(resolve=>release=resolve);return{bytes:new Uint8Array([137,80,78,71]),mime:'image/png'};}},'chapter.xhtml',h.projection,()=>true,()=>({width,height:400,pixelRatio:1,orientation:'landscape',colorScheme:'light',reducedMotion:false}),()=>changed++);assert.match(h.root.querySelector('ul').style.listStyleImage,/blob:responsive-marker-0/);width=800;result.refresh();await new Promise(resolve=>setImmediate(resolve));assert.deepEqual(reads,['small.png','large.png']);assert.equal(result.omitted,0);release();await new Promise(resolve=>setImmediate(resolve));assert.match(h.root.querySelector('ul').style.listStyleImage,/blob:responsive-marker-1/);assert.ok(changed>0);result.dispose();assert.deepEqual(revoked,made);}finally{h.close();}
 const stale=host('<body><ul style="list-style-image:var(--marker,url(late.png))"><li>Closed</li></ul></body>');let finish,current=true,started;const begun=new Promise(resolve=>started=resolve),late=[];stale.dom.window.URL.createObjectURL=()=>{late.push('blob:late');return'blob:late';};stale.dom.window.URL.revokeObjectURL=()=>{};try{const pending=applyPublisherStyles({...book(),image:async()=>{started();await new Promise(resolve=>finish=resolve);return{bytes:new Uint8Array([137,80,78,71]),mime:'image/png'};}},'chapter.xhtml',stale.projection,()=>current);await begun;current=false;finish();const result=await pending;result.dispose();assert.deepEqual(late,[]);assert.equal(stale.root.querySelector('ul').style.listStyleImage,'');}finally{stale.close();}
});
